--go
CREATE PROCEDURE [dbo].[SP_New_SavePropertyWiseItems](@XMLData XML,@CompanyId INT,@UserId INT)
AS
BEGIN
	--Insert XML into temp table --Added by Nivesh 2024-03-06
 	INSERT INTO TempPropertyWiseItemCopyXML (XmlDATA)
	SELECT CONVERT(VARCHAR(MAX),  @XMLData) 

	BEGIN TRY
		BEGIN TRANSACTION
		DECLARE @iDocID INT,@ItemCode VARCHAR(200),@HeaderId INT
		DECLARE @InsertedIDs_StockItemDetails TABLE (ID INT); --Added by Nivesh 2024-03-05
		Declare @tempStItDe int = null --Added by Nivesh 2024-03-05
  
		EXEC sp_xml_preparedocument @iDocID OUTPUT, @XMLData;
		 
		SELECT * INTO #TempData 
		FROM OPENXML(@iDocID,'/ArrayOfPropertyWiseItemsModel_new2/PropertyWiseItemsModel_new2',2)
		WITH   
		( Name VARCHAR(1000),
		  StockItemCode VARCHAR(200)	
		)

		IF(@CompanyId = 0)
		BEGIN
			RAISERROR('Company ID Invalid, Please Log In Again',16,1)
			ROLLBACK TRANSACTION
		END

		IF(@UserId = 0)
		BEGIN
			RAISERROR('User ID Invalid, Please Log In Again',16,1)
			ROLLBACK TRANSACTION
		END

		IF NOT EXISTS (SELECT 1 FROM Locations WHERE CompanyID= @CompanyId AND GroupName='MS')
		BEGIN
			RAISERROR('Selected Property does not have a Main Store',16,1)
			ROLLBACK TRANSACTION
			RETURN
		END
		 
		
		WHILE(SELECT COUNT (*) FROM #TempData )> 0
		BEGIN
			SELECT TOP(1) @ItemCode = StockItemCode FROM #TempData

			SET @HeaderId = NULL

			IF NOT EXISTS (SELECT 1 FROM StockItemHeaders WHERE StockItemCode=@ItemCode AND CompanyId= @CompanyId)
			BEGIN
				INSERT INTO StockItemHeaders
				SELECT TOP(1) @CompanyId,H.LocationId,H.StockItemCode,H.PLUCode,H.ReferanceCode,H.Barcode,H.Name,H.NameOnInvoice,H.ImageUrl,H.CategoryID,H.SubCategoryID,
				H.SupplierID,H.TaxGroupID,H.CostingMethod,H.Remarks,CASE WHEN H.IsExpiryDateApplicable IS NULL THEN 0 ELSE H.IsExpiryDateApplicable END,H.IPAddress,@UserId,@UserId,GETDATE(),GETDATE(),H.SubCategory2ID,
				CASE WHEN H.IsPriceEditable IS NULL THEN 0 ELSE H.IsPriceEditable END,H.MaintainPriceHistory,CASE WHEN H.Isbundle IS NULL THEN 0 ELSE H.Isbundle END,H.BrandedItem,H.GenericItemCode,
				CASE WHEN H.IsMultiplePrices IS NULL THEN 0 ELSE H.IsMultiplePrices END, CASE WHEN H.IsMultipleBarcode IS NULL THEN 0 ELSE H.IsMultipleBarcode END,
				CASE WHEN H.IsAllowDiscount IS NULL THEN 0 ELSE H.IsAllowDiscount END,CASE WHEN H.IsFractionItem IS NULL THEN 0 ELSE H.IsFractionItem END,
				CASE WHEN H.IsSerialNo IS NULL THEN 0 ELSE H.IsSerialNo END,CASE WHEN H.IsAllowReturnItem IS NULL THEN 0 ELSE H.IsAllowReturnItem END,
				CASE WHEN H.IsOpenPrice IS NULL THEN 0 ELSE H.IsOpenPrice END,H.ChargeHeaderID,CASE WHEN H.IsSellingItem IS NULL THEN 0 ELSE H.IsSellingItem END,
				ISNULL(H.ERPReferenceCode,''),
				ISNULL(H.IsProductionItem,0)
				FROM StockItemHeaders H
				INNER JOIN StockItemDetails D ON H.Id = D.StockItemHeaderID
				INNER JOIN Locations L ON L.Id = D.LocationID
				WHERE StockItemCode = @ItemCode	

				SET @HeaderId = SCOPE_IDENTITY();
			---------------------LOG StockItemHeaders INSERT Added by Nivesh 2024-03-05--------------
				IF (@HeaderId IS NOT NULL)
				BEGIN
					EXEC Inventry_AuditTail_WriteToLog 'StockItemHeaders', @HeaderId, 'INV', 'SIHI', 'I', @UserId,@CompanyId, '', ''
				END
			-----------------------------------------------------------------------------------------
			END

			IF (@HeaderId IS NOT NULL)
			BEGIN
				SELECT * INTO #TempLocations FROM Locations WHERE GroupName = 'MS' AND CompanyID = @CompanyId

				SELECT TOP(1) d.* INTO #TempDetails FROM StockItemDetails D
				INNER JOIN StockItemHeaders H ON H.id = D.StockItemHeaderID
				WHERE h.StockItemCode = @ItemCode

				INSERT INTO StockItemDetails
				OUTPUT INSERTED.Id INTO @InsertedIDs_StockItemDetails --Added by Nivesh 2024-03-05
				SELECT   @CompanyId,@CompanyId,TL.Id,@HeaderId,d.MasterUnitID ,d.PurchasingUnitID,d.MinimumQuantity,d.MaximumQuantity,d.ReOrderLevel,
				d.ReOrderQuantity,d.ReOrderPeriod,0,0,0,0,0,1,1,0,@HeaderId,'',@UserId,@UserId, GETDATE(),GETDATE(),null,0,0
				FROM #TempDetails d 
				CROSS JOIN #TempLocations TL
				
				----------------LOG StockItemDetails INSERT Added by Nivesh 2024-03-05----------------------------------------------
				WHILE EXISTS (SELECT 1 FROM @InsertedIDs_StockItemDetails)
				BEGIN
					SELECT TOP(1) @tempStItDe = Id FROM @InsertedIDs_StockItemDetails
					EXEC Inventry_AuditTail_WriteToLog 'StockItemDetails', @tempStItDe, 'INV', 'SIDI', 'I', @UserId,@CompanyId, '', ''
					DELETE TOP(1) FROM @InsertedIDs_StockItemDetails
				END
				-------------------------------------------------------------------------------------------------------------------------

				DROP TABLE #TempLocations
				DROP TABLE #TempDetails
			END
			DELETE TOP(1) FROM #TempData
		END
   
		COMMIT TRANSACTION
	END TRY
	BEGIN CATCH 
 
		ROLLBACK TRANSACTION
	
		DECLARE @ErrorMessage NVARCHAR(4000);  
		DECLARE @ErrorSeverity INT;  
		DECLARE @ErrorState INT;  

		SELECT   
		@ErrorMessage = ERROR_MESSAGE(),  
		@ErrorSeverity = ERROR_SEVERITY(),  
		@ErrorState = ERROR_STATE(); 
		RAISERROR (@ErrorMessage,@ErrorSeverity,@ErrorState);
	END CATCH
END

GO

